llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "A close analogue bearing an arylsulfonyl N-ethylpiperazine and a fused pyrazolopyrimidinone lactam had 34% oral bioavailability in fasting healthy volunteers, directly supporting F ≥20% for the query's sulfonamide–diazepane–quinolinone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Sildenafil, which shares the arylsulfonyl N-alkylpiperazine and heteroaromatic lactam motif, has an absolute oral bioavailability of about 40% in humans, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Niraparib, a basic-amine-containing heteroaromatic drug with high assay transfer, has an absolute oral bioavailability of approximately 73%, showing that ionizable basic amines are compatible with F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fenspiride, a low-molecular-weight basic amine with a lactam/oxazolidinone, showed about 90% absolute oral bioavailability in healthy volunteers, supporting high F for a similarly small ionizable lactam.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Gaboxadol, a hydrophilic small molecule, has high oral bioavailability in humans, demonstrating that low lipophilicity and ionization do not preclude F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Didanosine, a polar low-logD drug, showed 19% oral bioavailability in children with HIV, a sub-threshold value; however, this is formulation/population-specific and outweighed by adult didanosine values of 25–40%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer analogues, including close sulfonyl-piperazine/heteroaromatic lactam structures (sildenafil ~40%, analogue 34%) and polar/ionizable small molecules (niraparib ~73%, fenspiride ~90%, gaboxadol high), support F ≥20%. Occasional sub-20% values are special-population/formulation outliers. Prediction: high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule; closest analogues are more lipophilic.",
    "The query's very low neutral fraction (0.01) and logD -1.42 raise permeability uncertainty not fully resolved by analogues.",
    "Potential efflux/transporter effects for the diazepane sulfonamide are unknown.",
    "Dose-dependent absorption and food effects were not assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

